function lines(text: string): Line[] {
  const result: Line[] = [];
  const re = /([^\r\n]*)(\r\n|\r|\n|$)/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(text)) && (m[0].length || m.index < text.length)) {
